  "literacy.tutorial.title": "कलाकृति मे अपनेक स्वागत अछि — ई कोना काज करैत अछि",
  "literacy.tutorial.subtitle": "कारीगर के लिये डिजाइन किया गया। बिना तकनीकी कंप्यूटर कौशल के पूरा भारत में अपन शिल्प बेचू।",
  "literacy.tutorial.step1Title": "1. अपन मातृभाषा मे बाजू",
  "literacy.tutorial.step1Desc": "टाइप करबाक कोनो आवश्यकता नहि। बस अपन शिल्प के वर्णन करय वाला एकटा छोट आवाज नोट रिकॉर्ड करू. हमर एआई लिस्टिंग के ट्रांसक्रिप्ट आ लिखैत अछि।",
  "literacy.tutorial.step2Title": "2. स्वचालित एआई स्टूडियो प्रकाश व्यवस्था",
  "literacy.tutorial.step2Desc": "मोबाइल पर साधारण फोटो खींचू। हमरऽ एआई व्यस्त कार्यशाला पृष्ठभूमि क॑ साफ करै छै आरू प्राकृतिक प्रकाश क॑ संतुलित करै छै ।",
  "literacy.tutorial.step3Title": "3. उचित मूल्य सलाहकार",
