  'orderConfirmation.subtitleSuffix': 'सुरक्षित कए करघा मे पठा देल गेल अछि। अहां कें भुगतान कें 100% वैधानिक एस्क्रौ मे राखल गेल छै आ प्रेषण पर सीधा कारीगर कें स्थानांतरित कैल जेतय.',
