  'sellerShowcase.subtitle': '74 राष्ट्रीय शिल्प गलियाराक मे 12,000 सं बेसि सत्यापित ग्रामीण कारीगर, बुनकर, आ स्व-सहायता गिल्ड सं जुड़ू.',
  'sellerShowcase.testimonial.1.quote': 'हस्तनिर्मित धरोहर रचना के सुंदरता के प्रदर्शन करैत एकटा राष्ट्रीय पुरस्कार विजेता विक्रेता | कलाकृति के माध्यम स हम सब बिना कमीशन दलाल के सीधा वैश्विक संरक्षक स जुड़ैत छी।',
  'sellerShowcase.testimonial.2.quote': 'भारत सरकार द्वारा उपलब्ध कराओल गेल डिजिटल बुनियादी ढांचा के माध्यम स अपन 600 साल पुरान चांदी के जड़ल कला के वैश्विक स्तर पर प्रदर्शित करब। आदेश शून्य बिचौलियाक संग हमर गामक कार्यशाला धरि पहुँचैत अछि।',
  'sellerShowcase.testimonial.3.quote': 'हमर महिला सहकारी समिति कम साक्षरता वाला आवाज पीडब्ल्यूए के उपयोग क मिनट मे पंजीकरण केलक. दरबज्जा पर शीघ्र रसद आ डीबीटी बैंक निपटान स हमर पारंपरिक कमर करघा कए फेर स जीवित कैल गेल अछि।',
